package com.vityarthi.library.repository;
import com.vityarthi.library.db.Database; import com.vityarthi.library.model.Book; import java.sql.*; import java.util.*;
public class BookRepository {
 public void seed(){if(all().isEmpty()){insert(new Book(0,"9780134685991","Effective Java","Joshua Bloch",2018,2,2));insert(new Book(0,"9780596009205","Head First Java","Kathy Sierra",2005,3,3));insert(new Book(0,"9780132350884","Clean Code","Robert C. Martin",2008,2,2));}}
 public long insert(Book b){String q="INSERT INTO books(isbn,title,author,publication_year,total_copies,available_copies) VALUES(?,?,?,?,?,?)";try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement(q,Statement.RETURN_GENERATED_KEYS)){p.setString(1,b.getIsbn());p.setString(2,b.getTitle());p.setString(3,b.getAuthor());p.setInt(4,b.getPublicationYear());p.setInt(5,b.getTotalCopies());p.setInt(6,b.getAvailableCopies());p.executeUpdate();try(ResultSet k=p.getGeneratedKeys()){return k.next()?k.getLong(1):0;}}catch(SQLException e){throw new IllegalArgumentException("Could not add book: "+e.getMessage());}}
 public List<Book> all(){List<Book>x=new ArrayList<>();try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement("SELECT * FROM books ORDER BY title");ResultSet r=p.executeQuery()){while(r.next())x.add(map(r));return x;}catch(SQLException e){throw new IllegalStateException(e);}}
 public Optional<Book> byId(long id){try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement("SELECT * FROM books WHERE id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){return r.next()?Optional.of(map(r)):Optional.empty();}}catch(SQLException e){throw new IllegalStateException(e);}}
 public void availability(long id,int delta){String q="UPDATE books SET available_copies=available_copies+? WHERE id=? AND available_copies+? BETWEEN 0 AND total_copies";try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,delta);p.setLong(2,id);p.setInt(3,delta);if(p.executeUpdate()==0)throw new IllegalArgumentException("Invalid book availability change.");}catch(SQLException e){throw new IllegalStateException(e);}}
 private Book map(ResultSet r)throws SQLException{return new Book(r.getLong("id"),r.getString("isbn"),r.getString("title"),r.getString("author"),r.getInt("publication_year"),r.getInt("total_copies"),r.getInt("available_copies"));}
}